insert into questoes (id,materia,topico,tipo,enunciado,alternativas,aluno) values
  ('fis-t38','fisica','Módulo 10: Constelações','treino','Uma pessoa nasceu num dia em que o Sol, visto da Terra, estava na direção da constelação de Leão. Para a ASTRONOMIA, o que isso significa?','["Que Leão é a constelação mais próxima da Terra", "Que a pessoa só verá a constelação de Leão a vida toda", "Só que, naquela data, o Sol parecia estar sobre a região de Leão na eclíptica", "Que a pessoa terá uma personalidade corajosa"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('fis-t39','fisica','Módulo 10: Constelações','treino','Por que, ao longo do ano, o Sol parece passar por uma constelação do zodíaco diferente mais ou menos a cada mês?','["Porque as constelações mudam de lugar no céu todo mês", "Porque o Sol dá uma volta em torno da Terra a cada mês", "Porque a Terra gira em volta do Sol e, de cada ponto da órbita, vemos o Sol na frente de constelações diferentes", "Porque a Lua empurra o Sol de uma constelação para outra"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('fis-t40','fisica','Módulo 10: Constelações','treino','A eclíptica fica inclinada cerca de 23,5° em relação ao equador celeste. Qual é a causa dessa inclinação?','["O tamanho do Sol", "A velocidade da luz", "A distância entre a Terra e a Lua", "A inclinação do eixo de rotação da Terra"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('fis-t41','fisica','Módulo 10: Constelações','treino','A velocidade mínima para um satélite ficar em órbita é v = √(G·M/R), em que R é o raio da órbita (medido a partir do centro da Terra). Se o satélite for colocado numa órbita MAIS ALTA (R maior), essa velocidade:','["Aumenta", "Fica igual", "Diminui", "Vira zero"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('fis-t42','fisica','Módulo 10: Constelações','treino','Newton imaginou lançar um objeto na horizontal do alto de uma montanha, cada vez mais rápido. O que aconteceria com uma velocidade grande o suficiente?','["O objeto cairia cada vez mais perto da montanha", "O objeto ficaria parado no ar, flutuando", "O objeto continuaria caindo, mas sem nunca tocar o chão, dando voltas na Terra como a Lua", "O objeto subiria em linha reta até o Sol"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('fis-t43','fisica','Módulo 10: Constelações','treino','O que costuma acontecer com os satélites que param de funcionar?','["Transformam-se em satélites naturais, como a Lua", "Caem inteiros no mar e são reaproveitados", "Voltam sozinhos para a fábrica para serem consertados", "São trazidos de volta para queimar na atmosfera ou levados para órbitas \"cemitério\"; muitos viram lixo espacial"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('fis-t44','fisica','Módulo 11: Evolução estelar','treino','Como uma nebulosa dá origem a uma estrela?','["Um raio cai dentro da nuvem e a acende", "Um cometa bate na nuvem e a faz explodir em luz", "A gravidade junta o gás e a poeira, a nuvem se contrai e esquenta até começar a fusão do hidrogênio", "A nuvem esfria até congelar e começa a brilhar"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('fis-t45','fisica','Módulo 11: Evolução estelar','treino','Muito antes de o Sol virar uma gigante vermelha e engolir Mercúrio e Vênus, a Terra já terá deixado de ser habitável. Por quê?','["Porque a Terra vai parar de girar", "Porque a Lua vai se afastar e cair no Sol", "Porque o Sol vai esfriar e congelar a Terra", "Porque o Sol vai ficando aos poucos mais quente e emitindo mais radiação"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('fis-t46','fisica','Módulo 11: Evolução estelar','treino','No fim da vida de uma estrela como o Sol, forma-se uma "nebulosa planetária". Ela é:','["Uma nuvem de gelo vinda dos cometas", "Um planeta novo que nasce em volta da estrela", "As camadas externas da estrela espalhadas pelo espaço, formando uma nuvem de gás e poeira", "Uma pequena galáxia que se forma ao redor do Sol"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('fis-t47','fisica','Módulo 11: Evolução estelar','treino','Quando uma anã branca deixa de emitir luz, ela passa a ser chamada de:','["Supernova", "Anã negra", "Gigante vermelha", "Estrela de nêutrons"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('fis-t48','fisica','Módulo 11: Evolução estelar','treino','Nas estrelas massivas, a fusão vai formando elementos cada vez mais pesados (hélio, carbono, oxigênio, silício...). Em qual elemento essa sequência para?','["Carbono", "Ouro", "Ferro", "Hélio"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('fis-t49','fisica','Módulo 11: Evolução estelar','treino','Depois de uma supernova, o que decide se o núcleo que sobrou vira estrela de nêutrons ou buraco negro?','["A distância da estrela até a Terra", "A cor que a estrela tinha", "O número de planetas em volta da estrela", "A massa do núcleo: se for menor, vira estrela de nêutrons; se for maior, buraco negro"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('fis-t50','fisica','Módulo 11: Evolução estelar','treino','O material lançado no espaço pela explosão de uma supernova:','["Desaparece completamente", "Vira imediatamente um buraco negro", "Forma novas nebulosas, que podem dar origem a novas estrelas", "Volta todo para dentro da estrela"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf');
insert into gabarito (questao_id,correta,explicacao) values
  ('fis-t38',2,'Para a astronomia, o "signo" é apenas a constelação do zodíaco em que o Sol parecia estar na data do nascimento. Ligar isso à personalidade é astrologia, que não tem comprovação científica.'),
  ('fis-t39',2,'É o movimento de translação da Terra que muda o "fundo" de estrelas atrás do Sol. São 12 constelações zodiacais para 12 meses.'),
  ('fis-t40',3,'O eixo da Terra é inclinado; por isso o caminho aparente do Sol (eclíptica) não coincide com o equador celeste. Essa inclinação também causa as estações do ano.'),
  ('fis-t41',2,'R está no denominador, dentro da raiz: quanto maior o raio, menor a velocidade necessária. Satélites mais altos andam mais devagar.'),
  ('fis-t42',2,'Essa é a ideia de órbita: o objeto cai o tempo todo, mas a Terra é curva e "foge" por baixo dele. É assim que os satélites ficam em volta da Terra.'),
  ('fis-t43',3,'Satélites desativados são destruídos na reentrada ou afastados para órbitas de descarte. Os que ficam soltos fazem parte do lixo espacial.'),
  ('fis-t44',2,'Ao se contrair por causa da gravidade, a nuvem aquece. Quando a temperatura fica altíssima, o hidrogênio começa a se fundir em hélio: nasce a estrela.'),
  ('fis-t45',3,'O Sol aumenta de tamanho e de temperatura gradualmente. Bem antes da fase de gigante vermelha, o calor e a radiação já tornariam a Terra inabitável.'),
  ('fis-t46',2,'Apesar do nome, não tem nada a ver com planetas: são os restos externos da gigante vermelha. No centro, sobra a anã branca.'),
  ('fis-t47',1,'A anã branca não produz mais energia e vai esfriando. Quando para de brilhar, chama-se anã negra: o fim da vida de uma estrela como o Sol.'),
  ('fis-t48',2,'A estrutura do ferro não permite novas fusões que liberem energia. O núcleo de ferro, muito denso, colapsa e a estrela explode como supernova.'),
  ('fis-t49',3,'Núcleos de massa "pequena" viram estrelas de nêutrons; os de massa maior colapsam em buracos negros.'),
  ('fis-t50',2,'A supernova espalha elementos pesados pelo espaço. Essas nuvens formam novas nebulosas, berço de novas estrelas: o ciclo recomeça.');
